// windowsNode is a Windows model with the confirmation open on node.exe.
func windowsNode(t *testing.T) (*Model, *fakeProcs) {
	t.Helper()
	m := feed(t, portsModel(t), tea.WindowSizeMsg{Width: 160, Height: 40})
