	}
}

func TestAFailedKillStaysAFooterErrorWithoutTheFailedGlyph(t *testing.T) {
	m := feed(t, killingSSHD(t), portsKillResultMsg{pid: "812", err: fmt.Errorf("killing: %w", os.ErrPermission)})

